set -e; python3 - <<'PY'
from pathlib import Path
p=Path('app/src/main/java/pl/michalmatu/aicallbridge/shizuku/ShizukuUserServiceProbe.java')
s=p.read_text()
old='''    private final Runnable timeout = () -> finish(
        (live ? "probe=shizuku-user-service-live-v1" : "probe=shizuku-user-service-v1")
            + "\nerror=connect_timeout"
    );
'''
new='''    private final Runnable timeout = () -> finish(
        probeName() + "\nerror=connect_timeout"
    );
'''
if s.count(old) != 1:
    raise SystemExit('timeout block mismatch')
s=s.replace(old,new)
needle='''    private void start() {
'''
insert='''    private String probeName() {
        return live ? "probe=shizuku-user-service-live-v1" : "probe=shizuku-user-service-v1";
    }

'''
if s.count(needle) != 1:
    raise SystemExit('start method anchor mismatch')
s=s.replace(needle,insert+needle)
p.write_text(s)
